class Solution:
    def baseUnitConversions(self, conversions: List[List[int]]) -> List[int]:
        MOD = 10**9 + 7
        n = len(conversions) + 1
        g = [[] for _ in range(n)]
        for s, t, f in conversions:
            g[s].append((t, f))
        res = [0] * n
        stack = [(0, 1)]
        while stack:
            u, val = stack.pop()
            res[u] = val
            for v, f in g[u]:
                stack.append((v, val * f % MOD))
        return res

