class Solution {
    public int[] baseUnitConversions(int[][] conversions) {
        final long MOD = 1_000_000_007L;
        int n = conversions.length + 1;
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : conversions) g.get(e[0]).add(new int[]{e[1], e[2]});
        int[] res = new int[n];
        Deque<long[]> st = new ArrayDeque<>();
        st.push(new long[]{0, 1});
        while (!st.isEmpty()) {
            long[] top = st.pop();
            int u = (int) top[0];
            res[u] = (int) top[1];
            for (int[] ef : g.get(u)) st.push(new long[]{ef[0], top[1] * ef[1] % MOD});
        }
        return res;
    }
}

